import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/ui/Button';
import '../styles/pages/MapViewPage.css';

// Definición de tipo para las celdas del mapa
interface Tile {
  id: string;
  type: string;
  grassIndex: number;
}

// Ejemplo de cómo se verían los nombres de archivos correctos
const GRASS_IMAGES = [
  'grass_01.png',
  'grass_02.png',
  'grass_03.png',
  'grass_04.png'
];

const MapViewPage: React.FC = () => {
  const navigate = useNavigate();
  const [map, setMap] = useState<Tile[][]>([]);
  const [loading, setLoading] = useState(true);
  
  // Configuración del mapa
  const mapWidth = 20;
  const mapHeight = 15;
  
  useEffect(() => {
    // Generar mapa aleatorio con los diferentes tipos de césped
    generateRandomMap();
  }, []);
  
  const generateRandomMap = () => {
    setLoading(true);
    
    const newMap: Tile[][] = [];
    
    for (let y = 0; y < mapHeight; y++) {
      const row: Tile[] = [];
      for (let x = 0; x < mapWidth; x++) {
        // Seleccionar aleatoriamente un tipo de césped
        const randomIndex = Math.floor(Math.random() * GRASS_IMAGES.length);
        
        row.push({
          id: `tile-${x}-${y}`,
          type: 'grass',
          grassIndex: randomIndex
        });
      }
      newMap.push(row);
    }
    
    setMap(newMap);
    setLoading(false);
  };
  
  const handleRefreshMap = () => {
    generateRandomMap();
  };
  
  const handleBackToMenu = () => {
    navigate('/menu');
  };
  
  // Función para obtener la URL de la imagen basada en el índice
  const getImageSrc = (grassIndex: number) => {
    const imageName = GRASS_IMAGES[grassIndex];
    try {
      // Intentamos construir una URL relativa a la carpeta pública
      return `/assets/images/tiles/grass/${imageName}`;
    } catch (error) {
      console.error("No se pudo cargar la imagen:", error);
      // Devolver un color como fallback
      return `data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="%23${['8eb22c', '669922', '548c18', '7cac26'][grassIndex % 4]}"><rect width="48" height="48" /></svg>`;
    }
  };
  
  if (loading) {
    return <div className="loading-screen">Generando mapa...</div>;
  }
  
  return (
    <div className="map-view-page">
      <div className="map-view-header">
        <h1>Visor de Mapa</h1>
        <div className="map-controls">
          <Button onClick={handleRefreshMap}>Generar Nuevo Mapa</Button>
          <Button onClick={handleBackToMenu}>Volver al Menú</Button>
        </div>
      </div>
      
      <div className="map-container">
        <div 
          className="game-map-grid" 
          style={{ 
            gridTemplateColumns: `repeat(${mapWidth}, 48px)`,
            gridTemplateRows: `repeat(${mapHeight}, 48px)`
          }}
        >
          {map.flat().map((tile) => (
            <div key={tile.id} className="map-tile">
              <img 
                src={getImageSrc(tile.grassIndex)} 
                alt={`Tile ${tile.type}`} 
                className="tile-image"
                onError={(e) => {
                  // Si falla la carga, mostramos un color como fallback
                  const target = e.target as HTMLImageElement;
                  const index = tile.grassIndex % 4;
                  const colors = ['#8eb22c', '#669922', '#548c18', '#7cac26'];
                  target.style.backgroundColor = colors[index];
                  target.style.display = 'block';
                  target.style.width = '100%';
                  target.style.height = '100%';
                  target.removeAttribute('src');
                }}  
              />
            </div>
          ))}
        </div>
      </div>
      
      <div className="map-info">
        <h3>Información del mapa</h3>
        <p>Este mapa usa imágenes de grass de la carpeta: <code>/assets/images/tiles/grass/</code></p>
        <p>Archivos necesarios: {GRASS_IMAGES.join(', ')}</p>
        <p>Verifica que las imágenes existan en esta ubicación.</p>
      </div>
    </div>
  );
};

export default MapViewPage;
